STYLE = ('Use case: scientific-educational. Create one square editorial illustration for an adult TRIZ learning card. '
         'Crisp vector-like shapes, dark navy outlines (#163447), warm ivory background (#F7F3E9), restrained teal (#268B88) '
         'and orange (#E99049), subtle shadows, uncluttered composition, all essential objects within central 84 percent. ')

def write_json(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--force', action='store_true')
    args = parser.parse_args()
    dest = ROOT / 'data/principles.json'
    if dest.exists() and not args.force:
        raise SystemExit('Data exists. Edit data/principles.json directly; --force explicitly reseeds.')
    vi = json.loads((ROOT / 'src/Data/40principles_vi.json').read_text())
    en = json.loads((ROOT / 'data/40principles.json').read_text())
    evidence = (ROOT / 'data/evidence/noi-bo-2026-09-11.html').read_text()
    evidence_hash = hashlib.sha256(evidence.encode()).hexdigest()
    terms, cards = [], []
    for p, e, row in zip(vi, en, ROWS, strict=True):
        i = p['id']
        assert i == e['id'] and p['title'] in evidence
        name = p['title'].removeprefix('Nguyên tắc ')
        definition, hook, question, example, application, other, distinction, scene, alternative, show, avoid = row
        section = f'Danh sách bài giảng / nguyên tắc {i:02}'
        source = {'url':'https://trizvietnam.com/vi/noi-bo', 'section':section}
        terms.append({'id':i, 'original_name_vi':p['title'], 'display_name_vi':name, 'name_en':e['title'], 'aliases_vi':[],
                      'sources':[source], 'verification_status':'verified_designated_web_source', 'verified_at':'2026-09-11',
                      'evidence_path':'data/evidence/noi-bo-2026-09-11.html', 'evidence_sha256':evidence_hash,
                      'book_comparison_status':'not_independently_checked', 'display_rule':'remove_exact_prefix_only'})
        prompt = STYLE + '\nTeaching objective: ' + e['title'] + '.\nScene: ' + scene + '\nMust show: ' + show + '.\nAvoid: ' + avoid + '.\nNo text, letters, numbers, labels, logos, watermarks, card borders or arrows. Python supplies precise overlays.\n'
        if i == 1:
            prompt = (ROOT/'prompts/01.txt').read_text()
        cards.append({'id':i, 'name_vi':name, 'name_en':e['title'], 'aliases_vi':[], 'definition_vi':definition,
                      'memory_hook_vi':hook, 'front_question_vi':question, 'example_vi':example,
                      'mechanism_vi':example.split('. ')[0] + '.', 'benefit_vi':example.split('. ')[-1],
                      'application_question_vi':application, 'confusable_with':[other], 'distinction_vi':distinction,
                      'source_refs':[source, {'url':'https://the-trizjournal.com/40-inventive-principles-examples/', 'section':f'Principle {i}'},
                                     {'url':f'https://trizvietnam.com/vi/principles/{i}', 'section':f'Nguyên tắc {i}'}],
                      'visual_brief':{'scene':scene, 'layout':'controlled_diagram' if i in (9,23,36) else ('sequence' if i in (16,19,37) else 'editorial'),
                                      'alternatives':[{'scene_vi':example, 'assessment_vi':'Cơ chế có dấu hiệu vật lý trực tiếp trong must_show, đọc được trong một vùng hình vuông.'},
                                                      {'scene_vi':alternative, 'assessment_vi':'Hợp cơ chế nhưng cần thêm bối cảnh hoặc chi tiết nhỏ để phân biệt ở khổ thẻ.'}],
                                      'selection_reason_vi':f'Chọn cảnh thứ nhất; bằng chứng cần nhìn: {show}.',
                                      'must_show':show.split('; '), 'must_avoid':avoid.split('; '),
                                      'scope_note':'Minh họa một ứng dụng cụ thể; không bao quát mọi cách dùng nguyên tắc.'},
                      'image_prompt_en':prompt, 'overlay_spec':[], 'content_status':'editorially_reviewed'})
    # Coordinates normalized in a dedicated diagram inset, independent of AI geometry.
    cards[8]['overlay_spec'] = [{'kind':'prestress', 'stages':['Nén trước', 'Tải làm việc'], 'compression_arrows':[[0.1,0.3,0.3,0.3],[0.9,0.3,0.7,0.3]], 'load_arrow':[0.5,0.6,0.5,0.8], 'note':'Sơ đồ khái niệm; không dùng tính toán kết cấu.'}]
    cards[22]['overlay_spec'] = [{'kind':'feedback','nodes':['Điều khiển','Van','Đất','Cảm biến'], 'edges':[[0,1],[1,2],[2,3],[3,0]], 'note':'Đo ẩm → chỉnh van → đổi ẩm → đo lại.'}]
    cards[35]['overlay_spec'] = [{'kind':'heat','direction':'environment_to_pack','note':'Nhận nhiệt khi lõi đang tan.'}]
    cards[19]['overlay_spec'] = [{'kind':'passes','directions':['right','left']}]
    cards[21]['overlay_spec'] = [{'kind':'heat_recovery','direction':'waste_to_water'}]
    write_json(dest, cards)
    write_json(ROOT/'data/terminology_vi.json', terms)
    write_json(ROOT/'data/terminology_lock.json', {'sha256':hashlib.sha256((ROOT/'data/terminology_vi.json').read_bytes()).hexdigest(),
               'basis':'40 names match the user-designated web page and repository title table; not a book concordance.', 'locked_at':'2026-09-11'})
    print('Seeded and source-checked 40 cards and 40 terminology records.')

if __name__ == '__main__':
    main()
